-- Synthetic compliance register of a fictional grant recipient (CC0).
-- Cited paragraphs are verbatim 2 CFR Part 200 text (U.S. Government work, public domain).
CREATE TABLE compliance_register (assessment_id text PRIMARY KEY, policy_area text, section_id text, cited_ordinal int, cited_label text, cited_text text, cited_version date, conclusion text, owner text, assessed_on date, selection text, source_url text);
CREATE ROLE sentinel_reader LOGIN;
GRANT SELECT ON compliance_register TO sentinel_reader;
