INSERT INTO compliance_register VALUES ('NCHA-001', 'Definitions', '200.1', 66, '', 'Equipment means tangible personal property (including information technology systems) having a useful life of more than one year and a per-unit acquisition cost which equals or exceeds the lesser of the capitalization level established by the non-Federal entity for financial statement purposes, or $5,000. See also the definitions of capital assets, computing devices, general purpose equipment, information technology systems, special purpose equipment, and supplies in this section.', '2024-09-30', 'Our definitions procedure was reviewed against 2 CFR 200.1 as cited and found compliant.', 'Finance', '2024-06-14', 'anchor', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.1');
INSERT INTO compliance_register VALUES ('NCHA-002', 'Definitions', '200.1', 195, '', 'Modified Total Direct Cost (MTDC) means all direct salaries and wages, applicable fringe benefits, materials and supplies, services, travel, and up to the first $25,000 of each subaward (regardless of the period of performance of the subawards under the award). MTDC excludes equipment, capital expenditures, charges for patient care, rental costs, tuition remission, scholarships and fellowships, participant support costs and the portion of each subaward in excess of $25,000. Other items may only be excluded when necessary to avoid a serious inequity in the distribution of indirect costs, and with the approval of the cognizant agency for indirect costs.', '2024-09-30', 'Our definitions procedure was reviewed against 2 CFR 200.1 as cited and found compliant.', 'Procurement', '2024-06-14', 'anchor', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.1');
INSERT INTO compliance_register VALUES ('NCHA-003', 'Indirect costs', '200.414', 16, 'f', '(f) In addition to the procedures outlined in the appendices in paragraph (e) of this section, any non-Federal entity that does not have a current negotiated (including provisional) rate, except for those non-Federal entities described in appendix VII to this part, paragraph D.1.b, may elect to charge a de minimis rate of 10% of modified total direct costs (MTDC) which may be used indefinitely. No documentation is required to justify the 10% de minimis indirect cost rate. As described in § 200.403, costs must be consistently charged as either indirect or direct costs, but may not be double charged or inconsistently charged as both. If chosen, this methodology once elected must be used consistently for all Federal awards until such time as a non-Federal entity chooses to negotiate for a rate, which the non-Federal entity may apply to do at any time.', '2024-09-30', 'Our indirect costs procedure was reviewed against 2 CFR 200.414 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'anchor', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.414');
INSERT INTO compliance_register VALUES ('NCHA-004', 'Single audit', '200.501', 1, 'a', '(a) Audit required. A non-Federal entity that expends $750,000 or more during the non-Federal entity''s fiscal year in Federal awards must have a single or program-specific audit conducted for that year in accordance with the provisions of this part.', '2024-09-30', 'Our single audit procedure was reviewed against 2 CFR 200.501 as cited and found compliant.', 'Programme Management', '2024-06-14', 'anchor', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.501');
INSERT INTO compliance_register VALUES ('NCHA-005', 'Equipment', '200.313', 20, '1', '(1) Items of equipment with a current per unit fair market value of $5,000 or less may be retained, sold or otherwise disposed of with no further responsibility to the Federal awarding agency.', '2024-09-30', 'Our equipment procedure was reviewed against 2 CFR 200.313 as cited and found compliant.', 'Grants Office', '2024-06-14', 'anchor', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.313');
INSERT INTO compliance_register VALUES ('NCHA-006', 'Capital expenditures', '200.439', 4, '2', '(2) Capital expenditures for special purpose equipment are allowable as direct costs, provided that items with a unit cost of $5,000 or more have the prior written approval of the Federal awarding agency or pass-through entity.', '2024-09-30', 'Our capital expenditures procedure was reviewed against 2 CFR 200.439 as cited and found compliant.', 'Finance', '2024-06-14', 'anchor', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.439');
INSERT INTO compliance_register VALUES ('NCHA-007', 'Fixed amount subawards', '200.333', 1, '', 'With prior written approval from the Federal awarding agency, a pass-through entity may provide subawards based on fixed amounts up to the Simplified Acquisition Threshold, provided that the subawards meet the requirements for fixed amount awards in § 200.201.', '2024-09-30', 'Our fixed amount subawards procedure was reviewed against 2 CFR 200.333 as cited and found compliant.', 'Procurement', '2024-06-14', 'anchor', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.333');
INSERT INTO compliance_register VALUES ('NCHA-008', 'Record retention', '200.334', 4, 'c', '(c) Records for real property and equipment acquired with Federal funds must be retained for 3 years after final disposition.', '2024-09-30', 'Our record retention procedure was reviewed against 2 CFR 200.334 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'anchor', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.334');
INSERT INTO compliance_register VALUES ('NCHA-009', 'Fringe benefits', '200.431', 7, 'ii', '(ii) The accrual basis may be only used for those types of leave for which a liability as defined by GAAP exists when the leave is earned. When a non-Federal entity uses the accrual basis of accounting, allowable leave costs are the lesser of the amount accrued or funded.', '2024-09-30', 'Our fringe benefits procedure was reviewed against 2 CFR 200.431 as cited and found compliant.', 'Programme Management', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.431');
INSERT INTO compliance_register VALUES ('NCHA-010', 'Closeout', '200.344', 7, 'f', '(f) The non-Federal entity must account for any real and personal property acquired with Federal funds or received from the Federal Government in accordance with §§ 200.310 through 200.316 and 200.330.', '2024-09-30', 'Our closeout procedure was reviewed against 2 CFR 200.344 as cited and found compliant.', 'Grants Office', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.344');
INSERT INTO compliance_register VALUES ('NCHA-011', 'Fringe benefits', '200.431', 35, '6', '(6) The Federal Government must receive an equitable share of any amounts of previously allowed post-retirement benefit costs (including earnings thereon) which revert or inure to the non-Federal entity in the form of a refund, withdrawal, or other credit.', '2024-09-30', 'Our fringe benefits procedure was reviewed against 2 CFR 200.431 as cited and found compliant.', 'Finance', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.431');
INSERT INTO compliance_register VALUES ('NCHA-012', 'Entertainment', '200.438', 1, '', 'Costs of entertainment, including amusement, diversion, and social activities and any associated costs are unallowable, except where specific costs that might otherwise be considered entertainment have a programmatic purpose and are authorized either in the approved budget for the Federal award or with prior written approval of the Federal awarding agency.', '2024-09-30', 'Our entertainment procedure was reviewed against 2 CFR 200.438 as cited and found compliant.', 'Procurement', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.438');
INSERT INTO compliance_register VALUES ('NCHA-013', 'Indirect costs', '200.414', 4, '1', '(1) The negotiated rates must be accepted by all Federal awarding agencies. A Federal awarding agency may use a rate different from the negotiated rate for a class of Federal awards or a single Federal award only when required by Federal statute or regulation, or when approved by a Federal awarding agency head or delegate based on documented justification as described in paragraph (c)(3) of this section.', '2024-09-30', 'Our indirect costs procedure was reviewed against 2 CFR 200.414 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.414');
INSERT INTO compliance_register VALUES ('NCHA-014', 'Definitions', '200.1', 153, 'ii', '(ii) When an agency''s review is unable to discern whether a payment was proper as a result of insufficient or lack of documentation, this payment should also be considered an improper payment. When establishing documentation requirements for payments, agencies should ensure that all documentation requirements are necessary and should refrain from imposing additional burdensome documentation requirements.', '2024-09-30', 'Our definitions procedure was reviewed against 2 CFR 200.1 as cited and found compliant.', 'Programme Management', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.1');
INSERT INTO compliance_register VALUES ('NCHA-015', 'Allowable costs', '200.403', 9, 'h', '(h) Cost must be incurred during the approved budget period. The Federal awarding agency is authorized, at its discretion, to waive prior written approvals to carry forward unobligated balances to subsequent budget periods pursuant to § 200.308(e)(3).', '2024-09-30', 'Our allowable costs procedure was reviewed against 2 CFR 200.403 as cited and found compliant.', 'Grants Office', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.403');
INSERT INTO compliance_register VALUES ('NCHA-016', 'Fringe benefits', '200.431', 31, '4', '(4) When a non-Federal entity converts to an acceptable actuarial cost method and funds PRHP costs in accordance with this method, the initial unfunded liability attributable to prior years is allowable if amortized over a period of years in accordance with GAAP, or, if no such GAAP period exists, over a period negotiated with the cognizant agency for indirect costs.', '2024-09-30', 'Our fringe benefits procedure was reviewed against 2 CFR 200.431 as cited and found compliant.', 'Finance', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.431');
INSERT INTO compliance_register VALUES ('NCHA-017', 'Budget revisions', '200.308', 2, 'b', '(b) Recipients are required to report deviations from budget or project scope or objective, and request prior approvals from Federal awarding agencies for budget and program plan revisions, in accordance with this section.', '2024-09-30', 'Our budget revisions procedure was reviewed against 2 CFR 200.308 as cited and found compliant.', 'Procurement', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.308');
INSERT INTO compliance_register VALUES ('NCHA-018', 'Definitions', '200.1', 116, '2', '(2) When no Assistance Listings Number is assigned, all Federal awards from the same agency made for the same purpose must be combined and considered one program.', '2024-09-30', 'Our definitions procedure was reviewed against 2 CFR 200.1 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.1');
INSERT INTO compliance_register VALUES ('NCHA-019', 'Subrecipient monitoring', '200.332', 32, 'd', '(d) Monitor the activities of the subrecipient as necessary to ensure that the subaward is used for authorized purposes, in compliance with Federal statutes, regulations, and the terms and conditions of the subaward; and that subaward performance goals are achieved. Pass-through entity monitoring of the subrecipient must include:', '2024-09-30', 'Our subrecipient monitoring procedure was reviewed against 2 CFR 200.332 as cited and found compliant.', 'Programme Management', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.332');
INSERT INTO compliance_register VALUES ('NCHA-020', 'Closeout', '200.344', 3, 'b', '(b) Unless the Federal awarding agency or pass-through entity authorizes an extension, a non-Federal entity must liquidate all financial obligations incurred under the Federal award no later than 120 calendar days after the end date of the period of performance as specified in the terms and conditions of the Federal award.', '2024-09-30', 'Our closeout procedure was reviewed against 2 CFR 200.344 as cited and found compliant.', 'Grants Office', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.344');
INSERT INTO compliance_register VALUES ('NCHA-021', 'Payment', '200.305', 4, '2', '(2) Whenever possible, advance payments must be consolidated to cover anticipated cash needs for all Federal awards made by the Federal awarding agency to the recipient.', '2024-09-30', 'Our payment procedure was reviewed against 2 CFR 200.305 as cited and found compliant.', 'Finance', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.305');
INSERT INTO compliance_register VALUES ('NCHA-022', 'Budget revisions', '200.308', 26, '3', '(3) A revision is desired which involves specific costs for which prior written approval requirements may be imposed consistent with applicable OMB cost principles listed in subpart E.', '2024-09-30', 'Our budget revisions procedure was reviewed against 2 CFR 200.308 as cited and found compliant.', 'Procurement', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.308');
INSERT INTO compliance_register VALUES ('NCHA-023', 'Definitions', '200.1', 9, '', 'Auditee means any non-Federal entity that expends Federal awards which must be audited under subpart F of this part.', '2024-09-30', 'Our definitions procedure was reviewed against 2 CFR 200.1 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.1');
INSERT INTO compliance_register VALUES ('NCHA-024', 'Reporting', '200.329', 11, '1', '(1) Problems, delays, or adverse conditions which will materially impair the ability to meet the objective of the Federal award. This disclosure must include a statement of the action taken, or contemplated, and any assistance needed to resolve the situation.', '2024-09-30', 'Our reporting procedure was reviewed against 2 CFR 200.329 as cited and found compliant.', 'Programme Management', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.329');
INSERT INTO compliance_register VALUES ('NCHA-025', 'Budget revisions', '200.308', 12, 'd', '(d) No other prior approval requirements for specific items may be imposed unless an exception has been approved by OMB. See also §§ 200.102 and 200.407.', '2024-09-30', 'Our budget revisions procedure was reviewed against 2 CFR 200.308 as cited and found compliant.', 'Grants Office', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.308');
INSERT INTO compliance_register VALUES ('NCHA-026', 'Indirect costs', '200.414', 7, '4', '(4) As required under § 200.204, the Federal awarding agency must include in the notice of funding opportunity the policies relating to indirect cost rate reimbursement, matching, or cost share as approved under paragraph (e)(1) of this section. As appropriate, the Federal agency should incorporate discussion of these policies into Federal awarding agency outreach activities with non-Federal entities prior to the posting of a notice of funding opportunity.', '2024-09-30', 'Our indirect costs procedure was reviewed against 2 CFR 200.414 as cited and found compliant.', 'Finance', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.414');
INSERT INTO compliance_register VALUES ('NCHA-027', 'Budget revisions', '200.308', 3, 'c', '(c) For non-construction Federal awards, recipients must request prior approvals from Federal awarding agencies for the following program or budget-related reasons:', '2024-09-30', 'Our budget revisions procedure was reviewed against 2 CFR 200.308 as cited and found compliant.', 'Procurement', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.308');
INSERT INTO compliance_register VALUES ('NCHA-028', 'Audit reporting', '200.512', 12, 'd', '(d) Submission to FAC. The auditee must electronically submit to the FAC the data collection form described in paragraph (b) of this section and the reporting package described in paragraph (c) of this section.', '2024-09-30', 'Our audit reporting procedure was reviewed against 2 CFR 200.512 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.512');
INSERT INTO compliance_register VALUES ('NCHA-029', 'Fringe benefits', '200.431', 20, '5', '(5) Pension plan termination insurance premiums paid pursuant to the Employee Retirement Income Security Act (ERISA) of 1974 (29 U.S.C. 1301-1461) are allowable. Late payment charges on such premiums are unallowable. Excise taxes on accumulated funding deficiencies and other penalties imposed under ERISA are unallowable.', '2024-09-30', 'Our fringe benefits procedure was reviewed against 2 CFR 200.431 as cited and found compliant.', 'Programme Management', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.431');
INSERT INTO compliance_register VALUES ('NCHA-030', 'Capital expenditures', '200.439', 5, '3', '(3) Capital expenditures for improvements to land, buildings, or equipment which materially increase their value or useful life are unallowable as a direct cost except with the prior written approval of the Federal awarding agency, or pass-through entity. See § 200.436, for rules on the allowability of depreciation on buildings, capital improvements, and equipment. See also § 200.465.', '2024-09-30', 'Our capital expenditures procedure was reviewed against 2 CFR 200.439 as cited and found compliant.', 'Grants Office', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.439');
INSERT INTO compliance_register VALUES ('NCHA-031', 'Definitions', '200.1', 112, '1', '(1) The percentage of Federal participation in the total cost of the real property, equipment, or supplies; and', '2024-09-30', 'Our definitions procedure was reviewed against 2 CFR 200.1 as cited and found compliant.', 'Finance', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.1');
INSERT INTO compliance_register VALUES ('NCHA-032', 'Travel', '200.475', 5, 'c', '(c)(1) Temporary dependent care costs (as dependent is defined in 26 U.S.C. 152) above and beyond regular dependent care that directly results from travel to conferences is allowable provided that:', '2024-09-30', 'Our travel procedure was reviewed against 2 CFR 200.475 as cited and found compliant.', 'Procurement', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.475');
INSERT INTO compliance_register VALUES ('NCHA-033', 'Definitions', '200.1', 8, '', 'Audit finding means deficiencies which the auditor is required by § 200.516(a) to report in the schedule of findings and questioned costs.', '2024-09-30', 'Our definitions procedure was reviewed against 2 CFR 200.1 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.1');
INSERT INTO compliance_register VALUES ('NCHA-034', 'Audit reporting', '200.512', 1, 'a', '(a) General. (1) The audit must be completed and the data collection form described in paragraph (b) of this section and reporting package described in paragraph (c) of this section must be submitted within the earlier of 30 calendar days after receipt of the auditor''s report(s), or nine months after the end of the audit period. If the due date falls on a Saturday, Sunday, or Federal holiday, the reporting package is due the next business day.', '2024-09-30', 'Our audit reporting procedure was reviewed against 2 CFR 200.512 as cited and found compliant.', 'Programme Management', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.512');
INSERT INTO compliance_register VALUES ('NCHA-035', 'Travel', '200.475', 16, 'v', '(v) Offer accommodations not reasonably adequate for the traveler''s medical needs. The non-Federal entity must justify and document these conditions on a case-by-case basis in order for the use of first-class or business-class airfare to be allowable in such cases.', '2024-09-30', 'Our travel procedure was reviewed against 2 CFR 200.475 as cited and found compliant.', 'Grants Office', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.475');
INSERT INTO compliance_register VALUES ('NCHA-036', 'Procurement methods', '200.320', 15, 'i', '(i) In order for sealed bidding to be feasible, the following conditions should be present:', '2024-09-30', 'Our procurement methods procedure was reviewed against 2 CFR 200.320 as cited and found compliant.', 'Finance', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.320');
INSERT INTO compliance_register VALUES ('NCHA-037', 'Procurement standards', '200.318', 5, 'd', '(d) The non-Federal entity''s procedures must avoid acquisition of unnecessary or duplicative items. Consideration should be given to consolidating or breaking out procurements to obtain a more economical purchase. Where appropriate, an analysis will be made of lease versus purchase alternatives, and any other appropriate analysis to determine the most economical approach.', '2024-09-30', 'Our procurement standards procedure was reviewed against 2 CFR 200.318 as cited and found compliant.', 'Procurement', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.318');
INSERT INTO compliance_register VALUES ('NCHA-038', 'Audit reporting', '200.512', 2, '2', '(2) Unless restricted by Federal statutes or regulations, the auditee must make copies available for public inspection. Auditees and auditors must ensure that their respective parts of the reporting package do not include protected personally identifiable information.', '2024-09-30', 'Our audit reporting procedure was reviewed against 2 CFR 200.512 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.512');
INSERT INTO compliance_register VALUES ('NCHA-039', 'Travel', '200.475', 2, 'b', '(b) Lodging and subsistence. Costs incurred by employees and officers for travel, including costs of lodging, other subsistence, and incidental expenses, must be considered reasonable and otherwise allowable only to the extent such costs do not exceed charges normally allowed by the non-Federal entity in its regular operations as the result of the non-Federal entity''s written travel policy. In addition, if these costs are charged directly to the Federal award documentation must justify that:', '2024-09-30', 'Our travel procedure was reviewed against 2 CFR 200.475 as cited and found compliant.', 'Programme Management', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.475');
INSERT INTO compliance_register VALUES ('NCHA-040', 'Payment', '200.305', 38, '11', '(11) When returning funds or interest to PMS you must include the following as applicable:', '2024-09-30', 'Our payment procedure was reviewed against 2 CFR 200.305 as cited and found compliant.', 'Grants Office', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.305');
INSERT INTO compliance_register VALUES ('NCHA-041', 'Participant support', '200.456', 1, '', 'Participant support costs as defined in § 200.1 are allowable with the prior approval of the Federal awarding agency.', '2024-09-30', 'Our participant support procedure was reviewed against 2 CFR 200.456 as cited and found compliant.', 'Finance', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.456');
INSERT INTO compliance_register VALUES ('NCHA-042', 'Reporting', '200.329', 14, 'g', '(g) Performance report requirement waiver. The Federal awarding agency may waive any performance report required by this part if not needed.', '2024-09-30', 'Our reporting procedure was reviewed against 2 CFR 200.329 as cited and found compliant.', 'Procurement', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.329');
INSERT INTO compliance_register VALUES ('NCHA-043', 'Mandatory disclosures', '200.113', 1, '', 'The non-Federal entity or applicant for a Federal award must disclose, in a timely manner, in writing to the Federal awarding agency or pass-through entity all violations of Federal criminal law involving fraud, bribery, or gratuity violations potentially affecting the Federal award. Non-Federal entities that have received a Federal award including the term and condition outlined in appendix XII to this part are required to report certain civil, criminal, or administrative proceedings to SAM (currently FAPIIS). Failure to make required disclosures can result in any of the remedies described in § 200.339. (See also 2 CFR part 180, 31 U.S.C. 3321, and 41 U.S.C. 2313.)', '2024-09-30', 'Our mandatory disclosures procedure was reviewed against 2 CFR 200.113 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.113');
INSERT INTO compliance_register VALUES ('NCHA-044', 'Fringe benefits', '200.431', 2, 'b', '(b) Leave. The cost of fringe benefits in the form of regular compensation paid to employees during periods of authorized absences from the job, such as for annual leave, family-related leave, sick leave, holidays, court leave, military leave, administrative leave, and other similar benefits, are allowable if all of the following criteria are met:', '2024-09-30', 'Our fringe benefits procedure was reviewed against 2 CFR 200.431 as cited and found compliant.', 'Programme Management', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.431');
INSERT INTO compliance_register VALUES ('NCHA-045', 'Budget revisions', '200.308', 1, 'a', '(a) The approved budget for the Federal award summarizes the financial aspects of the project or program as approved during the Federal award process. It may include either the Federal and non-Federal share (see definition for Federal share in § 200.1) or only the Federal share, depending upon Federal awarding agency requirements. The budget and program plans include considerations for performance and program evaluation purposes whenever required in accordance with the terms and conditions of the award.', '2024-09-30', 'Our budget revisions procedure was reviewed against 2 CFR 200.308 as cited and found compliant.', 'Grants Office', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.308');
INSERT INTO compliance_register VALUES ('NCHA-046', 'Single audit', '200.501', 8, 'h', '(h) For-profit subrecipient. Since this part does not apply to for-profit subrecipients, the pass-through entity is responsible for establishing requirements, as necessary, to ensure compliance by for-profit subrecipients. The agreement with the for-profit subrecipient must describe applicable compliance requirements and the for-profit subrecipient''s compliance responsibility. Methods to ensure compliance for Federal awards made to for-profit subrecipients may include pre-award audits, monitoring during the agreement, and post-award audits. See also § 200.332.', '2024-09-30', 'Our single audit procedure was reviewed against 2 CFR 200.501 as cited and found compliant.', 'Finance', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.501');
INSERT INTO compliance_register VALUES ('NCHA-047', 'Fringe benefits', '200.431', 29, '2', '(2) PRHP costs calculated using an actuarial cost method recognized by GAAP are allowable if they are funded for that year within six months after the end of that year. Costs funded after the six-month period (or a later period agreed to by the cognizant agency) are allowable in the year funded. The Federal cognizant agency for indirect costs may agree to an extension of the six-month period if an appropriate adjustment is made to compensate for the timing of the charges to the Federal Government and related Federal reimbursements and the non-Federal entity''s contributions to the PRHP fund. Adjustments may be made by cash refund, reduction in current year''s PRHP costs, or other equitable procedures to compensate the Federal Government for the time value of Federal reimbursements in excess of contributions to the PRHP fund.', '2024-09-30', 'Our fringe benefits procedure was reviewed against 2 CFR 200.431 as cited and found compliant.', 'Procurement', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.431');
INSERT INTO compliance_register VALUES ('NCHA-048', 'Conflict of interest', '200.112', 1, '', 'The Federal awarding agency must establish conflict of interest policies for Federal awards. The non-Federal entity must disclose in writing any potential conflict of interest to the Federal awarding agency or pass-through entity in accordance with applicable Federal awarding agency policy.', '2024-09-30', 'Our conflict of interest procedure was reviewed against 2 CFR 200.112 as cited and found compliant.', 'Internal Audit', '2024-06-14', 'random', 'https://www.ecfr.gov/on/2024-09-30/title-2/section-200.112');
